-- =========================================================
-- Proyecto 9 — Carga de las comunas de Manizales a PostGIS
-- Fuente: 07-geoprocessing/data/comunas_validas.gpkg (geometrías corregidas en la 7.3)
-- CRS: EPSG:6256 (MAGNA-SIRGAS / Manizales urban grid)
--
-- Por qué un script y no DB Manager: QGIS no logró exportar la capa
-- ("SRID must be <= 998999") porque el GeoPackage guarda EPSG:6256 con la
-- definición vacía y QGIS lo trató como un CRS personalizado.
-- Requisito: EPSG:6256 registrado en spatial_ref_sys (ver postgis.sql).
-- Coordenadas redondeadas a 0,1 mm; todas las geometrías siguen siendo válidas.
-- =========================================================

DROP TABLE IF EXISTS monitoreo.comunas;

CREATE TABLE monitoreo.comunas (
    id_comuna  INTEGER PRIMARY KEY,          -- número oficial de la comuna (nro)
    nombre     VARCHAR(60) NOT NULL,
    area_km2   NUMERIC(8,4),                 -- calculada en el Proyecto 4
    geom       geometry(MultiPolygon, 6256) NOT NULL
);

