CREATE INDEX idx_comunas_geom ON monitoreo.comunas USING GIST (geom);

-- Verificación rápida: deben ser 12 comunas válidas y ~35,80 km² en total
-- (área en el plano de Manizales; en QGIS, $area sobre el elipsoide dio 35,77 km²)
SELECT COUNT(*) AS comunas,
       BOOL_AND(ST_IsValid(geom)) AS todas_validas,
       ROUND(SUM(ST_Area(geom))::numeric / 1e6, 2) AS area_total_km2
FROM monitoreo.comunas;
